 {view==='browse'&&<section className="container page-section"><div className="page-title"><div><span className="eyebrow">{t('عقارات سوريا','PROPERTY IN SYRIA')}</span><h1>{onlySaved?t('بيوت على قائمتك.','Your shortlist.'):t('مكان جديد. احتمالات جديدة.','New places. New possibilities.')}</h1><p>{t('ابحث عن مساحة تناسب حياتك.','Find a space that fits your life.')}</p></div><button className={'button '+(onlySaved?'tinted':'')} onClick={()=>setOnlySaved(v=>!v)}><Heart size={16}/>{t('المحفوظات','Saved homes')} ({favorites.length})</button></div><div className="filter-bar">{filters}</div>{extraFilters}<div className="results-line"><span>{filtered().length} {t('عقار','properties')}</span>{loading&&<LoaderCircle size={17} className="spin"/>}<button className="text-btn" onClick={()=>void load()}><RefreshCw size={13}/>{t('تحديث','Refresh')}</button></div>{error&&<div className="message error"><AlertCircle size={17}/>{t('تعذّر تحميل العقارات. حاول مجدداً.','Could not load properties. Please try again.')}<button onClick={()=>void load()}>{t('إعادة المحاولة','Retry')}</button></div>}{filtered().length?<div className="property-grid">{filtered().map(l=><Card l={l} key={l.id}/>)}</div>:!loading&&<Empty title={onlySaved?t('ابدأ بقائمة صغيرة من البيوت المفضلة','Start a shortlist of favourite homes'):t('لا توجد عقارات مطابقة حالياً','No matching properties yet')} text={onlySaved?t('احفظ العقارات التي تعجبك لتعود إليها بسهولة.','Save properties you like to return to them easily.'):t('جرّب تغيير خيارات البحث، أو عد قريباً لاكتشاف عقارات جديدة.','Try changing your filters, or come back soon for new listings.')} action={!demo&&<button className="button" onClick={()=>{setDemo(true);setPurpose('all');setCity('all');setKind('all');setOnlySaved(false);setQuery('')}}>{t('عرض أمثلة توضيحية','View illustrative examples')}</button>}/>}</section>}
