 {panel==='listings'&&listingAccess&&<><div className="dashboard-heading"><div><span className="eyebrow">{t('إدارة العقارات','PROPERTY MANAGEMENT')}</span><h1>{admin?t('مساحات تستحق المراجعة.','Spaces worth considering.'):t('عقاراتك، بوضوح.','Your properties, clearly.')}</h1><p>{t('من الإضافة إلى النشر، كل حالة في مكانها.','From submission to publication, every status in place.')}</p></div>{(admin||roles.includes('agent')||demo)&&<button className="button solid" onClick={()=>openEditor(null)}><Plus size={16}/>{t('إضافة عقار','Add property')}</button>}</div><div className="filter-bar">{filters}</div>{extraFilters}<div className="status-tabs">{['all','pending','approved','rejected','draft','suspended'].map(s=><button className={status===s?'active':''} key={s} onClick={()=>setStatus(s)}>{s==='all'?t('الكل','All'):statusLabel(s)}<span>{s==='all'?data.length:data.filter(l=>l.approval_status===s).length}</span></button>)}</div>{dashboardList(filtered(true))}</>}
 {panel==='leads'&&<><div className="dashboard-heading"><div><span className="eyebrow">{t('حديث يقود إلى خطوة','CONVERSATIONS THAT MOVE THINGS FORWARD')}</span><h1>{staff?t('استفسارات، وفرص جديدة.','Inquiries. New possibilities.'):t('محادثاتك تبدأ هنا.','Your conversations start here.')}</h1><p>{t('تابع حالة التواصل حول كل عقار.','Follow the conversation around each property.')}</p></div>{staff&&!sentView&&visibleInquiries.length>0&&<button className="button" onClick={exportLeads}><Download size={15}/>{t('تصدير CSV','Export CSV')}</button>}</div><div className="status-tabs" role="tablist" aria-label={t('نوع الاستفسارات','Inquiry direction')}>{staff&&<button role="tab" aria-selected={!sentView} className={!sentView?'active':''} onClick={()=>setInquiryTab('received')}>{admin?t('كل الاستفسارات الواردة','All received inquiries'):t('الاستفسارات الواردة','Received inquiries')} <span>{receivedInquiries.length}</span></button>}<button role="tab" aria-selected={sentView} className={sentView?'active':''} onClick={()=>setInquiryTab('sent')}>{t('استفساراتي المرسلة','My sent inquiries')} <span>{sentInquiries.length}</span></button></div>{visibleInquiries.length?<div className="lead-list">{visibleInquiries.map(l=><button className="lead-row" key={l.id} onClick={()=>void openLead(l)}><span className="initial">{l.customer_name.slice(0,1)}</span><div><strong>{l.customer_name}</strong><p>{marketplaceData.find(p=>p.id===l.listing_id)?.title||t('استفسار عن عقار','Property inquiry')}</p><small>{l.message}</small></div><span className={'badge '+l.status}>{statusLabel(l.status)}</span><span className="lead-date">{date(l.created_at,lang)}</span><ArrowUpLeft size={16}/></button>)}</div>:<Empty title={t('مساحة للمحادثة القادمة','Room for the next conversation')} text={t('ستظهر استفسارات العقارات هنا عند إرسالها.','Property inquiries will appear here when submitted.')}/>}</>}
 {panel==='people'&&admin&&<PeoplePanel admin={admin} onCreate={()=>{setTeamAction(false);setTeamOfficeId(null);setUserActionError('');setUserEditor(null)}} onEdit={p=>{setTeamAction(false);setTeamOfficeId(null);if(!admin&&(p.id===user?.id||allMembers.some(m=>m.user_id===p.id&&m.office_role==='manager'))){notify(t('حسابات المديرين تُدار من إدارة المنصة.','Manager accounts are managed by platform administration.'));return}setUserActionError('');setUserEditor(p)}} onRemove={p=>{setTeamAction(false);setTeamOfficeId(null);if(!admin&&allMembers.some(m=>m.user_id===p.id&&m.office_role==='manager')){notify(t('لا يمكنك إزالة مدير مكتب.','You cannot remove an office manager.'));return}setUserActionError('');setRemoveUser(p)}} people={currentPeople} roles={demo?demoPeople.map(p=>({user_id:p.id,role:'agent'})):allRoles} lang={lang} userId={user?.id||null} busy={busy} demo={demo} onRole={(id,role,enabled)=>void setRole(id,role,enabled)} onStatus={async p=>{setBusy(true);const {error}=await supabase.rpc('admin_set_account_status',{p_user_id:p.id,p_status:p.account_status==='active'?'suspended':'active'});if(error)notify(error.message);else await load();setBusy(false)}}/>}
 {panel==='offices'&&(admin||officeManager)&&<OfficesPanel userId={user?.id||(demo?'demo-manager':null)} onAddMember={office=>{setTeamAction(true);setTeamOfficeId(office);setUserActionError('');setUserEditor(null)}} onEditMember={(p,office)=>{setTeamAction(true);setTeamOfficeId(office);setUserActionError('');setUserEditor(p)}} onRemoveMember={(p,office)=>{setTeamAction(true);setTeamOfficeId(office);setUserActionError('');setRemoveUser(p)}} offices={assignmentOffices} members={demo?workspaceMemberships:allMembers} people={demo?[...currentPeople,{id:'demo-manager',full_name:lang==='ar'?'نور علي · تجريبي':'Noor Ali · Demo',phone:'',account_status:'active',created_at:'2026-10-25T08:00:00Z'},{id:'demo-staff',full_name:lang==='ar'?'ريم حسن · تجريبي':'Reem Hassan · Demo',phone:'',account_status:'active',created_at:'2026-10-25T08:00:00Z'}]:currentPeople} listings={marketplaceData} lang={lang} admin={admin} busy={busy} demo={demo} onCreate={manageOffice} onMember={addMember} onVerify={async o=>{setBusy(true);const {error}=await supabase.from('offices').update({verification_status:o.verification_status==='verified'?'pending':'verified'}).eq('id',o.id);if(error)notify(error.message);else await load();setBusy(false)}}/>}
 {panel==='locations'&&admin&&<><div className="dashboard-heading"><div><span className="eyebrow">{t('خريطة العمل','WHERE WE WORK')}</span><h1>{t('المواقع والمحافظات.','Locations & governorates.')}</h1></div></div><div className="location-list">{(demo?cities.map((name,i)=>({id:String(i),name,enabled:true})):locations).map(l=><div className="location-row" key={l.id}><MapPin size={17}/><strong>{l.name}</strong><label className="check-label"><input type="checkbox" checked={l.enabled} disabled={busy||demo} onChange={async e=>{const enabled=e.target.checked;setBusy(true);const {error}=await supabase.from('locations').update({enabled}).eq('id',l.id);if(error)notify(error.message);else await load();setBusy(false)}}/>{t('متاح','Enabled')}</label></div>)}</div><form className="form-card inline-form" onSubmit={addLocation}><label>{t('مدينة أو موقع جديد','New city or location')}<input name="name" minLength={2} maxLength={120} required/></label><button className="button solid" disabled={busy}><Plus size={15}/>{t('إضافة','Add')}</button></form></>}
 {panel==='settings'&&<><div className={'profile-page profile-theme-'+profileAccess}><div className="profile-page-heading"><h1>{t('حسابي','My account')}</h1><p>{t('بياناتك الشخصية وتفاصيل مكتبك، في مكان واحد.','Your personal details and office, in one place.')}</p></div><div className="profile-identity"><span className="profile-avatar">{(demo?'Noor Ali':profile?.full_name||'Bayt').split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('')}</span><div><h2>{demo?t('نور علي','Noor Ali'):profile?.full_name||t('حساب بيت','Bayt account')}</h2><p dir="ltr">{demo?'preview@example.com':user?.email}</p><span className="profile-access-label">{profileAccessLabel}</span></div>{(demo||profile?.account_status==='active')&&<span className="profile-active"><span/>{t('حساب نشط','Account active')}</span>}</div><div className="account-layout"><div className="profile-personal"><div className="profile-section-title"><Settings size={19}/><h2>{t('البيانات الشخصية','Personal information')}</h2></div><form className="form-card profile-form" onSubmit={async e=>{e.preventDefault();if(demo){notify(t('هذا ملف توضيحي فقط','This is a sample profile'));return}const f=new FormData(e.currentTarget);setBusy(true);const {error}=await supabase.from('profiles').update({full_name:String(f.get('name')),phone:String(f.get('phone'))}).eq('id',user!.id);if(error)notify(error.message);else{await load();notify(t('تم حفظ بيانات الحساب','Account details saved'))}setBusy(false)}}><label>{t('الاسم الكامل','Full name')}<input name="name" required maxLength={160} defaultValue={demo?'نور علي':profile?.full_name||''}/></label><label>{t('رقم الهاتف','Phone')}<input name="phone" type="tel" maxLength={40} defaultValue={profile?.phone||''}/></label><label>{t('البريد الإلكتروني','Email')}<input value={user?.email||'preview@example.com'} disabled dir="ltr"/></label><div className="profile-save-row"><p>{t('حافظ على تحديث بيانات التواصل.','Keep your contact details up to date.')}</p><button className="button solid" disabled={busy}><Busy/>{t('حفظ التغييرات','Save changes')}</button></div></form>{!demo&&<button className="text-btn profile-password-link" onClick={()=>showAuth('reset')}>{t('إعادة تعيين كلمة المرور','Reset your password')}</button>}</div><AccountAffiliations lang={lang} members={demo?(demoRole==='admin'?[]:workspaceMemberships.filter(m=>m.user_id===(demoRole==='office'?'demo-manager':demoRole==='staff'?'demo-staff':'demo-agent'))):members} offices={assignmentOffices}/></div></div></>}
