 {!workspaceMode&&<footer className="footer"><div className="container footer-top"><button className="brand-link" onClick={()=>go('home')}><HouseLogo/></button><p>{t('مساحة لبداية جديدة.','A place for a new beginning.')}</p><div><button onClick={()=>go('about')}>{t('عن بيت','About')}</button><button onClick={()=>go('privacy')}>{t('الخصوصية','Privacy')}</button><button onClick={()=>go('terms')}>{t('الشروط','Terms')}</button><button onClick={()=>go('dashboard')}>{t('مساحة الأعمال','Workspace')}</button></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} {t('بيت. كل بداية لها مكان.','Bayt. Every beginning has a place.')}</span><span>{t('نسخة أولى · تطبيق الهاتف قادم لاحقاً','First release · Native mobile app to follow')}</span></div></footer>}
 {userEditor!==false&&<Modal title={teamAction?(userEditor?t('تعديل عضو الفريق','Edit team member'):t('إضافة عضو للفريق','Add team member')):userEditor?t('تعديل المستخدم','Edit user'):t('إضافة مستخدم','New user')} onClose={()=>setUserEditor(false)}>{userActionError&&<p className="form-error user-action-error" role="alert">{userActionError}</p>}<UserEditor teamMode={teamAction} officeId={teamOfficeId} key={(userEditor?.id||'new')+(teamOfficeId||'')} person={userEditor} offices={assignmentOffices} members={demo?workspaceMemberships:allMembers} admin={admin} lang={lang} busy={busy} onSave={saveUserAccount}/></Modal>}
 {removeUser&&<Modal title={admin&&!teamAction?t('حذف المستخدم','Delete user'):t('إزالة عضوية المكتب','Remove office membership')} onClose={()=>setRemoveUser(null)}><form className="user-editor-form" onSubmit={e=>{e.preventDefault();void removeUserAccount(teamOfficeId||String(new FormData(e.currentTarget).get('office_id')||'')||null)}}><h3>{removeUser.full_name}</h3><p>{admin&&!teamAction?t('سيُوقف الحساب ويُؤرشف مع الاحتفاظ بالسجلات. يجب إعادة إسناد العقارات والاستفسارات النشطة أولاً.','The account will be suspended and archived while records are preserved. Reassign active properties and inquiries first.'):t('سيُوقف وصول هذا العضو إلى المكتب المحدد. يبقى حسابه وعضوياته الأخرى كما هي.','This membership will be suspended. Their account and other memberships remain available.')}</p>{(!admin||teamAction)&&<label>{t('المكتب','Office')}<select defaultValue={teamOfficeId||''} disabled={!!teamOfficeId} name="office_id" required>{assignmentOffices.filter(o=>(demo?workspaceMemberships:allMembers).some(m=>m.user_id===removeUser.id&&m.office_id===o.id)).map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select></label>}{userActionError&&<p className="form-error" role="alert">{userActionError}</p>}<button className="button danger full" disabled={busy}>{admin&&!teamAction?t('تأكيد الحذف','Confirm deletion'):t('تأكيد الإزالة','Confirm removal')}</button></form></Modal>}
 {auth&&<Modal title={auth==='signin'?t('أهلاً بعودتك إلى بيت','Welcome home'):auth==='signup'?t('تبدأ حكايتك هنا','Your story starts here'):auth==='reset'?t('استعادة الحساب','Reset your password'):auth==='confirm'?t('تأكيد بريدك الإلكتروني','Confirm your email'):t('كلمة مرور جديدة','New password')} onClose={()=>setAuth(null)}><form onSubmit={handleAuth} className="auth-form"><p>{auth==='confirm'?t('أدخل بريدك الإلكتروني لإرسال رابط تأكيد جديد. لا تحتاج كلمة مرور.','Enter your email to receive a new confirmation link. No password needed.'):auth==='signup'?t('أنشئ حسابك لحفظ العقارات والتواصل مع الوكلاء. حسابات الأعمال تُفعّل من الإدارة.','Create your account to save homes and contact agents. Business access is assigned by an administrator.'):t('مساحتك للعقارات والخطوات القادمة.','Your space for properties and next steps.')}</p>{auth==='newpassword'&&<p role="status">{recoveryReady?t('اختر كلمة مرور جديدة من 8 أحرف على الأقل، ثم أكدها أدناه.','Choose a new password of at least 8 characters, then confirm it below.'):t('جاري التحقق من رابط الاستعادة…','Verifying your reset link…')}</p>}{auth==='signup'&&<label>{t('الاسم الكامل','Full name')}<input name="name" autoComplete="name" minLength={2} maxLength={160} required/></label>}{auth!=='newpassword'&&<label>{t('البريد الإلكتروني','Email')}<input name="email" type="email" autoComplete="email" required dir="ltr"/></label>}{auth!=='reset'&&auth!=='confirm'&&<label>{auth==='newpassword'?t('كلمة المرور الجديدة','New password'):t('كلمة المرور','Password')}<input name="password" type="password" minLength={8} maxLength={128} autoComplete={auth==='signin'?'current-password':'new-password'} required dir="ltr"/></label>}{auth==='newpassword'&&<label>{t('تأكيد كلمة المرور الجديدة','Confirm new password')}<input name="confirm_password" type="password" minLength={8} maxLength={128} autoComplete="new-password" required dir="ltr"/></label>}{authError&&<p className="form-error" role="alert">{Array.isArray(authError)?t(authError[0],authError[1]):authError}</p>}{authNote&&<p className="message success" role="status">{authNote}</p>}<button type="submit" className="button solid full" disabled={busy||(auth==='newpassword'&&!recoveryReady)}><Busy/>{auth==='signin'?t('تسجيل الدخول','Sign in'):auth==='signup'?t('إنشاء الحساب','Create account'):auth==='reset'?t('إرسال رابط الاستعادة','Send reset link'):auth==='confirm'?t('إعادة إرسال رسالة التأكيد','Resend confirmation email'):t('حفظ كلمة المرور','Save password')}</button>{auth==='signin'&&<button type="button" className="text-btn" onClick={()=>showAuth('reset')}>{t('نسيت كلمة المرور؟','Forgot password?')}</button>}{auth==='signin'&&<button type="button" className="text-btn" onClick={()=>showAuth('confirm')}>{t('إعادة إرسال تأكيد البريد','Resend confirmation email')}</button>}{auth!=='newpassword'&&<div className="auth-switch">{auth==='signin'?t('ليس لديك حساب؟','New here?'):t('لديك حساب؟','Already have an account?')}<button type="button" className="text-btn" onClick={()=>showAuth(auth==='signin'?'signup':'signin')}>{auth==='signin'?t('إنشاء حساب','Create an account'):t('تسجيل الدخول','Sign in')}</button></div>}</form></Modal>}
 {selected&&<Modal title={admin&&view==='dashboard'?t('مراجعة العقار','Property review'):t('تفاصيل العقار','Property details')} onClose={()=>setSelected(null)} wide><div className="listing-detail"><div className="detail-photo"><img src={safeImage(selected.image_urls[imageIndex])||'/images/courtyard.jpg'} alt={selected.title}/>{demo&&<span className="image-tag">{t('صور وبيانات توضيحية','Illustrative images & data')}</span>}</div>{selected.image_urls.length>1&&<div className="gallery-thumbs">{selected.image_urls.map((url,i)=><button className={i===imageIndex?'active':''} key={url} onClick={()=>setImageIndex(i)} aria-label={t('الصورة','Photo')+' '+(i+1)}><img src={safeImage(url)} alt=""/></button>)}</div>}<div className="detail-heading"><div><span className={'badge '+selected.approval_status}>{statusLabel(selected.approval_status)}</span><h2>{selected.title}</h2><p className="location"><MapPin size={15}/>{selected.city}، {selected.district}</p></div><div className="detail-price"><bdi>{price(selected,lang)}</bdi><small>{selected.purpose==='rent'?(selected.rent_period==='year'?t('سنوياً','per year'):t('شهرياً','per month')):t('للبيع','For sale')}</small></div></div><div className="detail-facts"><span><Home size={18}/>{typeLabel(selected.property_type)}</span><span><BedDouble size={18}/>{selected.bedrooms} {t('غرف','beds')}</span><span><Bath size={18}/>{selected.bathrooms}</span><span><Maximize size={18}/>{selected.area_sqm} {t('م²','m²')}</span></div><p className="detail-description">{selected.description}</p>
 {view==='dashboard'&&(admin||(isAgent&&selected.agent_user_id===(demo?inquiryUserId:user?.id))||(officeManager&&workspaceMemberships.some(m=>m.office_id===selected.office_id&&m.office_role==='manager'&&m.membership_status==='active')))?<><div className="detail-operations"><h3>{t('إدارة الإعلان','Manage listing')}</h3><p className="small-note">{t('الوكيل المسؤول: ','Responsible agent: ')}{currentPeople.find(p=>p.id===selected.agent_user_id)?.full_name||profile?.id===selected.agent_user_id&&profile.full_name||t('غير معيّن لوكيل معروف','Not assigned to a known agent')}</p><div className="hero-cta"><button className="button" disabled={busy||selected.approval_status==='suspended'&&!admin} onClick={()=>{openEditor(selected);setSelected(null)}}>{t('تعديل التفاصيل','Edit details')}</button><label className="availability-select">{t('توفر العقار','Availability')}<select value={selected.availability_status} disabled={busy} onChange={e=>void availability(selected,e.target.value)}>{['available','sold','rented','unavailable'].map(s=><option value={s} key={s}>{statusLabel(s)}</option>)}</select></label></div></div>{admin&&<div className="review-box"><h3>{t('قرار المراجعة','Review decision')}</h3><label>{t('ملاحظة المراجعة','Review note')}<textarea value={reviewNote} onChange={e=>setReviewNote(e.target.value)} placeholder={t('سبب الرفض مطلوب عند رفض الإعلان','A reason is required when rejecting a listing')} rows={3} maxLength={3000}/></label><div className="hero-cta"><button className="button solid" disabled={busy||selected.approval_status==='approved'} onClick={()=>void moderate('approved')}><Busy/><Check size={16}/>{t('اعتماد ونشر','Approve & publish')}</button><button className="button" disabled={busy} onClick={()=>void moderate('rejected')}>{t('رفض الإعلان','Reject listing')}</button><button className="text-btn danger" disabled={busy} onClick={()=>void moderate('suspended')}>{t('إيقاف','Suspend')}</button></div></div>}{reviews.length>0&&<div className="review-history"><h3>{t('سجل المراجعة','Review history')}</h3>{reviews.map(r=><div key={r.id}><span className={'badge '+r.decision}>{statusLabel(r.decision)}</span><span>{date(r.created_at,lang)}</span><p>{r.reason}</p></div>)}</div>}</>:selected.availability_status!=='available'?<div className="message">{statusLabel(selected.availability_status)} · {t('هذا العقار لم يعد متاحاً للاستفسارات الجديدة.','This property is no longer available for new inquiries.')}</div>:<form className="inquiry-form" onSubmit={submitInquiry}><h3>{t('ابدأ حديثاً حول هذا البيت','Start a conversation about this home')}</h3><p>{t('ستصل رسالتك ومعلومات التواصل إلى الوكيل المسؤول.','Your message and contact details will reach the responsible agent.')}</p><div className="form-grid"><label>{t('اسمك','Your name')}<input name="name" required minLength={2} maxLength={160} defaultValue={profile?.full_name||''}/></label><label>{t('رقم الهاتف','Phone number')}<input name="phone" type="tel" required minLength={5} maxLength={40} defaultValue={profile?.phone||''}/></label></div><label>{t('رسالتك','Message')}<textarea name="message" rows={3} minLength={5} maxLength={3000} required defaultValue={t('مرحباً، أود معرفة المزيد وتحديد موعد للمعاينة.','Hello, I would like to learn more and arrange a viewing.')}/></label><button className="button solid" disabled={busy||selected.approval_status!=='approved'}><Busy/><Inbox size={16}/>{t('إرسال الاستفسار','Send inquiry')}</button>{selected.approval_status!=='approved'&&<p className="small-note">{t('لم يُنشر هذا العقار بعد. يمكنك اعتماده من لوحة الإدارة التجريبية.','This property is not published yet. Approve it from the demo admin dashboard.')}</p>}</form>}</div></Modal>}
 {edit!==false&&<Modal title={edit?t('تعديل العقار','Edit property'):t('أضف مساحة جديدة','Add a new property')} onClose={()=>setEdit(false)} wide><form className="listing-form" onSubmit={saveListing}>{admin&&<fieldset className="assignment-fields"><legend>{t('مسؤولية العقار','Property responsibility')}</legend><label>{t('الوكيل المسؤول','Responsible agent')}<select name="agent_user_id" required value={listingAgent} onChange={e=>{setListingAgent(e.target.value);setListingOffice('')}}><option value="">{t('اختر وكيلاً','Select an agent')}</option>{listingAgent&&!assignableAgents.some(p=>p.id===listingAgent)&&<option value={listingAgent} disabled>{t('المالك الحالي ليس وكيلاً نشطاً؛ اختر وكيلاً','Current owner is not an active agent; choose an agent')}</option>}{assignableAgents.map(p=><option value={p.id} key={p.id}>{p.full_name||p.id}</option>)}</select></label>{!assignableAgents.length&&<p className="form-error">{t('لا يوجد وكلاء نشطون. فعّل دور وكيل لأحد المستخدمين من صفحة المستخدمين أولاً.','No active agents yet. Assign agent access to a user from People first.')}</p>}<label>{t('المكتب (اختياري)','Office (optional)')}<select name="office_id" value={listingOffice} onChange={e=>setListingOffice(e.target.value)} disabled={!listingAgent}><option value="">{t('عقار مستقل','Independent listing')}</option>{assignmentOffices.filter(o=>o.account_status==='active'&&allowedOfficeIds.includes(o.id)).map(o=><option value={o.id} key={o.id}>{o.name}</option>)}</select></label><p className="small-note">{t('يظهر العقار في لوحة الوكيل المحدد. يبقى ضمن العقارات العامة بعد اعتماده فقط.','This property appears in the selected agent’s workspace. It becomes publicly visible only after approval.')}</p>{edit&&<p className="small-note">{t('الاستفسارات السابقة تحتفظ بالوكيل المعيّن لها. يمكنك تغيير إسنادها من صفحة الاستفسارات.','Existing inquiries keep their assigned agent. Reassign them separately from Inquiries.')}</p>}</fieldset>}<p className="small-note">{t('يُرسل الإعلان للمراجعة قبل نشره. تعديل التفاصيل يعيد العقار إلى قائمة المراجعة.','Listings are reviewed before publication. Editing details sends a property back to review.')}</p><label>{t('عنوان الإعلان','Listing title')}<input name="title" required minLength={5} maxLength={160} defaultValue={edit?.title||''}/></label><div className="form-grid"><label>{t('المحافظة','Governorate')}<select name="city" required defaultValue={edit?.city||''}><option value="">{t('اختر المحافظة','Select governorate')}</option>{(locations.length?locations.filter(l=>l.enabled).map(l=>l.name):cities).map(c=><option key={c}>{c}</option>)}</select></label><label>{t('الحي أو المنطقة','Neighbourhood')}<input name="district" required minLength={2} maxLength={160} defaultValue={edit?.district||''}/></label><label>{t('نوع العرض','Purpose')}<select name="purpose" defaultValue={edit?.purpose||'sale'}><option value="sale">{t('بيع','Sale')}</option><option value="rent">{t('إيجار','Rent')}</option></select></label><label>{t('نوع العقار','Property type')}<select name="property_type" defaultValue={edit?.property_type||'apartment'}>{['apartment','house','villa','land','commercial'].map(k=><option value={k} key={k}>{typeLabel(k)}</option>)}</select></label><label>{t('السعر','Price')}<input name="price" type="number" required min="1" max="999999999999" step="0.01" defaultValue={edit?.price||''}/></label><label>{t('العملة','Currency')}<select name="currency" defaultValue={edit?.currency||'USD'}><option>USD</option><option>SYP</option></select></label><label>{t('دورة الإيجار (للإيجار فقط)','Rental period (rent only)')}<select name="rent_period" defaultValue={edit?.rent_period||'month'}><option value="month">{t('شهري','Monthly')}</option><option value="year">{t('سنوي','Yearly')}</option></select></label><label>{t('المساحة بالمتر المربع','Area in square metres')}<input name="area_sqm" type="number" required min="1" max="9999999" defaultValue={edit?.area_sqm||''}/></label><label>{t('غرف النوم','Bedrooms')}<input name="bedrooms" type="number" min="0" max="50" defaultValue={edit?.bedrooms??0} required/></label><label>{t('الحمامات','Bathrooms')}<input name="bathrooms" type="number" min="0" max="50" defaultValue={edit?.bathrooms??0} required/></label></div>{!admin&&!edit&&!demo&&members.filter(m=>m.membership_status==='active').length>0&&<label>{t('المكتب (اختياري)','Office (optional)')}<select name="office_id"><option value="">{t('عقار مستقل','Independent listing')}</option>{members.filter(m=>m.membership_status==='active').map(m=><option value={m.office_id} key={m.office_id}>{offices.find(o=>o.id===m.office_id)?.name||m.office_id}</option>)}</select></label>}<label>{t('وصف العقار','Description')}<textarea name="description" rows={4} minLength={20} maxLength={10000} required defaultValue={edit?.description||''}/></label><label className="upload-zone"><Upload size={24}/><strong>{t('صور العقار','Property photos')}</strong><span>{t('حتى 8 صور · JPG / PNG / WebP · 5 MB للصورة','Up to 8 images · JPG / PNG / WebP · 5 MB each')}</span><input name="images" type="file" accept="image/jpeg,image/png,image/webp" multiple required={!edit&&!demo}/></label>{edit&&<p className="small-note">{t('اختر صوراً جديدة لاستبدال الصور الحالية، أو اترك الحقل فارغاً للاحتفاظ بها.','Choose new images to replace the current photos, or leave empty to keep them.')}</p>}{demo&&<p className="small-note">{t('في المعاينة، نستخدم صورة توضيحية بدلاً من رفع ملفاتك.','In preview mode, an illustrative image is used instead of uploading files.')}</p>}<button className="button solid full" disabled={busy||(admin&&!assignableAgents.some(p=>p.id===listingAgent))}><Busy/>{t('حفظ وإرسال للمراجعة','Save & submit for review')}<ArrowUpLeft size={16}/></button></form></Modal>}
 {leadDetail&&<Modal wide title={t('تفاصيل الاستفسار','Inquiry details')} onClose={()=>{setLeadDetail(null);setNotes([])}}><div className="inquiry-detail-layout"><InquiryProperty key={leadDetail.listing_id} listing={leadProperty} lang={lang} onOpen={()=>{if(leadProperty){setLeadDetail(null);setNotes([]);void openListing(leadProperty)}}}/><form className="lead-detail inquiry-contact-panel" onSubmit={updateLead}><div className="inquiry-contact-heading"><span className="eyebrow">{sentView?t('استفسارك المرسل','YOUR SENT INQUIRY'):t('تفاصيل صاحب الاستفسار','INQUIRER DETAILS')}</span><div className="inquiry-person"><span className="initial">{leadDetail.customer_name.slice(0,1)}</span><div><h3>{leadDetail.customer_name}</h3><p>{sentView?t('أرسلت هذا الاستفسار','You sent this inquiry'):t('مهتم بهذا العقار','Interested in this property')}</p></div><span className={'badge '+leadDetail.status}>{statusLabel(leadDetail.status)}</span></div></div><dl className="inquiry-contact-facts"><div><dt>{t('رقم التواصل','Contact number')}</dt><dd>{leadDetail.customer_phone?<a href={'tel:'+leadDetail.customer_phone.replace(/[^+\d]/g,'')}><Phone size={15}/><bdi>{leadDetail.customer_phone}</bdi></a>:t('لم يُقدّم رقم هاتف','No phone number provided')}</dd></div><div><dt>{t('تاريخ الاستفسار','Received on')}</dt><dd>{new Intl.DateTimeFormat(lang==='ar'?'ar-SY':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(leadDetail.created_at))}</dd></div></dl><section className="inquiry-message"><h4>{t('الرسالة','Message')}</h4><blockquote>{leadDetail.message}</blockquote></section><div className="inquiry-followup"><h4>{canEditInquiry?t('المتابعة','Follow-up'):t('متابعة الاستفسار','Inquiry progress')}</h4>{canReassign?<label>{t('المسؤول عن المتابعة','Assigned to')}<select value={leadDetail.assigned_agent_user_id} disabled={busy||demo} onChange={async e=>{const nextId=e.target.value;setBusy(true);const {error}=await supabase.rpc('assign_lead',{p_lead_id:leadDetail.id,p_agent_user_id:nextId});if(error)notify(error.message);else{setLeadDetail({...leadDetail,assigned_agent_user_id:nextId});await load();notify(t('تم إسناد الاستفسار','Inquiry reassigned'))}setBusy(false)}}>{!reassignmentOptions.some(p=>p.id===leadDetail.assigned_agent_user_id)&&<option value={leadDetail.assigned_agent_user_id}>{currentPeople.find(p=>p.id===leadDetail.assigned_agent_user_id)?.full_name||t('المسؤول المعيّن حالياً','Currently assigned person')}</option>}{reassignmentOptions.map(p=><option key={p.id} value={p.id}>{p.full_name||p.id}</option>)}</select></label>:<p className="small-note">{t('المسؤول عن المتابعة: ','Assigned to: ')}{currentPeople.find(p=>p.id===leadDetail.assigned_agent_user_id)?.full_name||(leadDetail.assigned_agent_user_id===inquiryUserId?profile?.full_name:t('عضو الفريق المسؤول','Responsible team member'))}</p>}{canEditInquiry?<><InquiryStatusPicker key={leadDetail.id} initial={leadDetail.status} statuses={leadStatuses} label={statusLabel} title={t('حالة الاستفسار','Inquiry status')}/><label>{t('ملاحظة داخلية','Internal note')}<textarea name="note" rows={3} maxLength={3000} placeholder={t('لن تظهر الملاحظة للعميل','Not visible to the customer')}/></label><button className="button solid" disabled={busy}><Busy/>{t('حفظ المتابعة','Save follow-up')}</button>{notes.length>0&&<section className="notes"><h3>{t('الملاحظات السابقة','Previous notes')}</h3>{notes.map(n=><div key={n.id}><p>{n.note}</p><small>{date(n.created_at,lang)}</small></div>)}</section>}</>:<span className={'badge '+leadDetail.status}>{statusLabel(leadDetail.status)}</span>}</div></form></div></Modal>}
 {notice&&<div className="toast" role="status"><CheckCircle2 size={18}/><span>{notice}</span><button aria-label={t('إغلاق','Close')} onClick={()=>setNotice('')}><X size={16}/></button></div>}
 </>
